4	import { motion } from 'framer-motion';
5	import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';
6	import { useUiCopy } from 'app/hooks/useUiCopy';
7	
8	const ZIMM_DRAWER_RECIPE = 'ZimmDrawer';
9	
10	// framer-motion's `Transition.ease` wants a literal, mutable 4-tuple (`BezierDefinition`) — a
11	// plain array literal infers as `number[]`, and `as const` infers a *readonly* tuple, neither of
12	// which satisfies it, hence the explicit cast.
13	const BEZIER_SLIDES_EASING = [0.87, 0, 0.13, 1] as [number, number, number, number];
14	// Mirrors theme/foundation/motion.ts's `duration.default` (300ms) and `easing.slides`
15	// (cubic-bezier(0.87, 0, 0.13, 1), "panels and overlays entering the screen") — hand-converted
16	// to framer-motion's shape (seconds, not ms; a bezier tuple, not a CSS `cubic-bezier()` string)
17	// since motion.ts's tokens are CSS-string form and framer-motion doesn't accept that form. One
18	// shared value for both enter and exit — that symmetry is the whole point (SFCC-898).
19	const DRAWER_TRANSITION = { duration: 0.3, ease: BEZIER_SLIDES_EASING };
20	
21	// `motion(chakra.div)` — framer OUTSIDE, chakra INSIDE. This ordering matters: framer's
22	// `motion()` only intercepts its own known animation props (initial/animate/exit/transition/
23	// variants) and forwards everything else straight to the wrapped component, so `transition`
24	// reaches framer-motion directly here. Chakra's OWN internal Drawer does the reverse
25	// (`chakra(Slide)`) — chakra wraps the animated component — and chakra's `shouldForwardProp`
26	// treats any prop literally named `transition` as a CSS shorthand style prop (it's a real
27	// Chakra/styled-system prop name), silently swallowing it before it ever reaches the wrapped
28	// component's real props (confirmed directly in @chakra-ui/system's should-forward-prop.js).
29	// That's why `<DrawerContent transition={...}>` had no effect and why this file no longer uses
30	// Chakra's `<DrawerContent>` at all — SFCC-898's close-animation defect (asymmetric enter/exit;
31	// Chakra's own Slide defaults to a spring-physics enter vs. a fixed 150ms tween exit, per
32	// @chakra-ui/transition's slide.js) can't be fixed through any prop that component exposes.
33	const MotionChakraDiv = motion(chakra.div);
34	
35	// Matches Figma's own named drawer sizes exactly (SFCC-898) — see zimmDrawer.css.ts's
36	// file-level comment for the width/usage table. `xLarge` has no consumer yet (Cart is a full
37	// page today, not a drawer).
38	export type ZimmDrawerSize = 'large' | 'tablet' | 'small' | 'xLarge' | 'mobile' | 'prompt';
39	
40	type ZimmDrawerBaseProps = {
41	  /** Whether the drawer is open. */
42	  isOpen: boolean;
43	  /** Called on backdrop click, Escape, and the close button (all via Chakra's Drawer). */
44	  onClose: () => void;
45	  /** Desktop/tablet width variant — see ZimmDrawerSize. Collapses to the mobile treatment
46	   *  below the tablet breakpoint regardless of which value is chosen — see zimmDrawer.css.ts. */
47	  size: ZimmDrawerSize;
48	  children: React.ReactNode;
49	  /** Text style for the title. 'large' applies heading1 (24px, uppercase, Futura Round regular);
50	   *  'small' applies body2Strong (14px bold). Defaults to 'large'. Only relevant when `title`
51	   *  is provided. */
52	  titleStyle?: 'large' | 'small';
53	  /** Element to focus when the drawer closes. Use when the trigger may not have received
54	   *  keyboard focus before opening (e.g. mouse click) — without this Chakra falls back to
55	   *  document.body and AC10 focus-return fails. */
56	  finalFocusRef?: React.RefObject<HTMLElement>;
57	  /** Element to focus when the drawer opens. Overrides Chakra's default (first focusable element
58	   *  in the panel, usually the close button) — use to land focus directly on the primary input. */
59	  initialFocusRef?: React.RefObject<HTMLElement>;
60	};
61	
62	/**
63	 * Exactly one of:
64	 * - `title`       — renders an inline header row (title left, close button right); the drawer's
65	 *                   accessible name is derived from the rendered title element automatically.
66	 * - `labelledBy`  — ID of an existing element that labels the drawer (e.g. ZimmPdpDrawer's own
67	 *                   tab header). Paired with the floating close button.
68	 * - `aria-label`  — explicit string label when neither a visible title nor a separate element
69	 *                   is available.
70	 */
71	type ZimmDrawerProps = ZimmDrawerBaseProps &
72	  (
73	    | { title: string; labelledBy?: never; 'aria-label'?: never }
74	    | { title?: never; labelledBy: string; 'aria-label'?: never }
75	    | { title?: never; labelledBy?: never; 'aria-label': string }
76	  );
77	
78	// Deliberately not named `ZimmDrawerContentProps` — scripts/generateRegistry.mjs's
79	// extractTsProps merges every `*Props`-suffixed type in a file into one component's registry
80	// row when it can't isolate the preferred one (ZimmDrawerProps' multi-line union body isn't
81	// matched by its regex, which can't cross a newline — a documented limitation, not a bug to
82	// patch there). That merge was leaking this internal helper's own fields (ariaLabel,
83	// contentStyles, closeButtonStyles) into ZimmDrawer's public registry entry.
84	type ZimmDrawerContentConfig = {
85	  children: React.ReactNode;
86	  onClose: () => void;
87	  /** Renders an inline header row (title left, close button right) instead of the floating
88	   *  close button when provided — see ZimmDrawerProps' `title` member. */
89	  title?: string;
90	  titleId?: string;
91	  titleStyle?: 'large' | 'small';
92	  labelledBy?: string;
93	  ariaLabel?: string;
94	  contentStyles: SystemStyleObject;
95	  headerStyles: SystemStyleObject;
96	  headerTitleStyles: SystemStyleObject;
97	  closeButtonStyles: SystemStyleObject;
98	};
99	
100	/**
101	 * Replaces Chakra's own `<DrawerContent>` — see the `MotionChakraDiv` comment above for why.
102	 * Reuses Chakra's real dialog/focus/aria mechanics directly (`useModalContext`,
103	 * `ModalFocusScope` — both genuinely public exports, not reaching into Chakra internals) so
104	 * focus trap, initial focus, focus restore, body-scroll lock, and Escape/overlay-click-to-close
105	 * all still come from Chakra exactly as before; only the slide transition itself is now ours.
106	 *
107	 * Renders either an inline title row (title left, close button right) when `title` is passed, or
108	 * a floating close button only — see ZimmDrawer's own docblock for when each is used.
109	 *
110	 * @param props see ZimmDrawerContentConfig
111	 */
112	const ZimmDrawerContent = ({
113	  children,
114	  onClose,
115	  title,
116	  titleId,
117	  titleStyle = 'large',
118	  labelledBy,
119	  ariaLabel,
120	  contentStyles,
121	  headerStyles,
122	  headerTitleStyles,
123	  closeButtonStyles,
124	}: ZimmDrawerContentConfig) => {
125	  const { t } = useUiCopy();
126	  const { getDialogProps, getDialogContainerProps } = useModalContext();
127	  const dialogProps = getDialogProps({ 'aria-label': ariaLabel });
128	  // getDialogProps always computes `aria-labelledby` from Chakra's own <DrawerHeader> mount
129	  // state, which ZimmDrawer never renders (no header sub-component in this tree) — so it
130	  // always resolves to undefined regardless of what's passed in above. Set it directly so the
131	  // `title` and `labelledBy` prop variants of ZimmDrawerProps actually work.
132	  if (title && titleId) {
133	    dialogProps['aria-labelledby'] = titleId;
134	  } else if (labelledBy) {
135	    dialogProps['aria-labelledby'] = labelledBy;
136	  }
137	  const containerProps = getDialogContainerProps();
138	
139	  return (
140	    <ModalFocusScope>
141	      <chakra.div {...containerProps} __css={{ position: 'fixed', inset: 0, display: 'flex', zIndex: 'modal' }}>
142	        <MotionChakraDiv
143	          {...dialogProps}
144	          initial={{ x: '100%' }}
145	          animate={{ x: 0 }}
146	          exit={{ x: '100%' }}
147	          transition={DRAWER_TRANSITION}
148	          __css={{ position: 'fixed', top: 0, right: 0, bottom: 0, outline: 0, ...contentStyles }}
149	        >
150	          {title ? (
151	            <chakra.div sx={headerStyles}>
152	              <chakra.span
153	                id={titleId}
154	                sx={headerTitleStyles}
155	                textStyle={titleStyle === 'small' ? 'body2Strong' : 'heading1'}
156	              >
157	                {title}
158	              </chakra.span>
159	              <ZimmButton variant="icon" icon="close" label={t('drawer.close', 'Close')} onClick={onClose} />
160	            </chakra.div>
161	          ) : (
162	            <chakra.div sx={closeButtonStyles}>
163	              <ZimmButton variant="icon" icon="close" label={t('drawer.close', 'Close')} onClick={onClose} />
164	            </chakra.div>
165	          )}
166	          {children}
167	        </MotionChakraDiv>
168	      </chakra.div>
169	    </ModalFocusScope>
170	  );
171	};
172	
173	/**
174	 * Generic right-anchored slide-in drawer shell — overlay, panel, and a Figma-matched size
175	 * variant (see ZimmDrawerSize), built on Chakra's Drawer primitive (focus trap, initial focus,
176	 * focus restore, body-scroll lock, and Escape/overlay-click-to-close all come from Chakra, not
177	 * hand-rolled).
178	 *
179	 * Pass `title` to render an inline header row (title text left, close button right) sized per the
180	 * Figma drawer/header frames. Omit `title` and pass `labelledBy`/`aria-label` instead for drawers
181	 * that supply their own header (e.g. ZimmPdpDrawer's tab row), which keeps the floating close
182	 * button behaviour.
183	 *
184	 * @param props see ZimmDrawerProps
185	 */
186	export const ZimmDrawer = (props: ZimmDrawerProps) => {
187	  const { isOpen, onClose, size, children, titleStyle = 'large', finalFocusRef, initialFocusRef } = props;
188	  const styles = useMultiStyleConfig(ZIMM_DRAWER_RECIPE, { variant: size });
189	  const titleId = useId();
190	
191	  const title = 'title' in props ? props.title : undefined;
192	  const labelledBy = !title && 'labelledBy' in props ? props.labelledBy : undefined;
193	  const ariaLabel = !title && 'aria-label' in props ? props['aria-label'] : undefined;
194	
195	  // Chakra's FocusLock remains active during the exit animation, so any focus call made
196	  // while the drawer is still mounted (rAF, close-button onClick) gets trapped and dropped.
197	  // onCloseComplete fires after the animation finishes and FocusLock is released — the only
198	  // reliable moment to restore focus. Covers both close-button click and Escape for all
199	  // consumers that pass finalFocusRef.
200	  const handleCloseComplete = () => {
201	    if (finalFocusRef) finalFocusRef.current?.focus();
202	  };
203	
204	  return (
205	    <Drawer
206	      isOpen={isOpen}
207	      onClose={onClose}
208	      placement="right"
209	      onCloseComplete={handleCloseComplete}
210	      initialFocusRef={initialFocusRef}
211	    >
212	      <DrawerOverlay sx={styles.overlay} />
213	      {/* aria-labelledby (not aria-label) for the title case: Chakra's own <DrawerContent>
214	          would clobber it with its own headingId (undefined without a DrawerHeader), but
215	          ZimmDrawerContent bypasses <DrawerContent> entirely and sets dialogProps itself
216	          (see its own comment above) — the clobbering bug this would otherwise work around
217	          doesn't apply here, so referencing the visible title node is safe and preferred. */}
218	      <ZimmDrawerContent
219	        onClose={onClose}
220	        title={title}
221	        titleId={title ? titleId : undefined}
222	        titleStyle={titleStyle}
223	        labelledBy={labelledBy}
224	        ariaLabel={ariaLabel}
225	        contentStyles={styles.content}
226	        headerStyles={styles.header}
227	        headerTitleStyles={styles.headerTitle}
228	        closeButtonStyles={styles.closeButton}
229	      >
230	        {children}
231	      </ZimmDrawerContent>
232	    </Drawer>
233	  );
234	};
