// jsdom has no IntersectionObserver or Element.scrollIntoView.
let latestObserverCallback: IntersectionObserverCallback | null = null;
class MockIntersectionObserver {
  constructor(callback: IntersectionObserverCallback) {
    latestObserverCallback = callback;
  }
  observe = vi.fn();
  disconnect = vi.fn();
  unobserve = vi.fn();
}

let scrollIntoViewMock: ReturnType<typeof vi.fn>;

beforeEach(() => {
  latestObserverCallback = null;
  // @ts-expect-error - jsdom has no native IntersectionObserver
  global.IntersectionObserver = MockIntersectionObserver;
  scrollIntoViewMock = vi.fn();
  Element.prototype.scrollIntoView = scrollIntoViewMock;
  // jsdom has no matchMedia — ChakraProvider's colour-mode detection needs it.
  window.matchMedia = vi.fn().mockImplementation((query: string) => ({
    matches: false,
    media: query,
    addListener: vi.fn(),
    removeListener: vi.fn(),
    addEventListener: vi.fn(),
    removeEventListener: vi.fn(),
    dispatchEvent: vi.fn(),
  }));
});

// Same jsdom limitation ZimmProductGallery's own tests document: `@media` blocks are parsed but
// never evaluated, so desktopHeader (unconditioned base `display: none`) stays hidden and
// mobileHeader (unconditioned base visible) stays visible in every test render regardless of
