  alt: `Photo ${n}`,
});
const SEVEN = Array.from({ length: 7 }, (_, i) => photo(i + 1));

const wrap = (ui: React.ReactElement) =>
  render(
    <IntlProvider locale="en" defaultLocale="en">
      <ChakraProvider theme={theme}>{ui}</ChakraProvider>
