  test('SFCC-731 AC 20 — renders nothing when media is empty, even if open', () => {
    wrap(<ZimmGalleryOverlay isOpen productName="Denim Dress" onClose={vi.fn()} media={[]} />);
    expect(screen.queryByRole('dialog')).not.toBeInTheDocument();
