    wrap(<ZimmGalleryOverlay isOpen productName="Denim Applique Mini Dress" onClose={vi.fn()} media={SEVEN} />);
    const dialog = await screen.findByRole('dialog');
    expect(dialog).toHaveAccessibleName('Denim Applique Mini Dress');
  });
});

describe('ZimmGalleryOverlay — close (AC 12/13)', () => {
  test('the close button fires onClose', async () => {
    const user = userEvent.setup();
    const onClose = vi.fn();
    wrap(<ZimmGalleryOverlay isOpen productName="Denim Dress" onClose={onClose} media={SEVEN} />);
    await user.click(await screen.findByRole('button', { name: 'Close gallery' }));
    expect(onClose).toHaveBeenCalledTimes(1);
