});

describe('ZimmGalleryOverlay — thumbnail strip (AC 14/16)', () => {
  test('renders one keyboard-focusable thumbnail per media item, labelled with its position', async () => {
    wrap(<ZimmGalleryOverlay isOpen productName="Denim Dress" onClose={vi.fn()} media={SEVEN} />);
    expect(await screen.findByRole('button', { name: 'Go to image 1 of 7', hidden: true })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Go to image 7 of 7', hidden: true })).toBeInTheDocument();
  });

  test('no thumbnail strip for a single image', async () => {
    wrap(<ZimmGalleryOverlay isOpen productName="Denim Dress" onClose={vi.fn()} media={[photo(1)]} />);
    await screen.findByRole('dialog');
    expect(screen.queryByRole('button', { name: /^Go to image/, hidden: true })).not.toBeInTheDocument();
  });

  test('a thumbnail click scrolls to the corresponding image — a real, independently operable control', async () => {
    const user = userEvent.setup();
    wrap(<ZimmGalleryOverlay isOpen productName="Denim Dress" onClose={vi.fn()} media={SEVEN} />);
    const thumb = await screen.findByRole('button', { name: 'Go to image 3 of 7', hidden: true });
    await user.click(thumb);
    expect(scrollIntoViewMock).toHaveBeenCalled();
  });

  test('ArrowRight/ArrowLeft move focus between thumbnails, wrapping at each end', async () => {
    const user = userEvent.setup();
    wrap(<ZimmGalleryOverlay isOpen productName="Denim Dress" onClose={vi.fn()} media={SEVEN} />);
    const thumb1 = await screen.findByRole('button', { name: 'Go to image 1 of 7', hidden: true });
    const thumb2 = screen.getByRole('button', { name: 'Go to image 2 of 7', hidden: true });
    const thumb7 = screen.getByRole('button', { name: 'Go to image 7 of 7', hidden: true });

    // waitFor, not a plain assertion — this overlay is wrapped in Chakra's Modal, which enables
    // react-focus-lock (its focus trap). FocusLock does its own rAF-scheduled reconciliation of
    // the currently focused element, which can land a tick after our own keydown handler's
    // synchronous `.focus()` call — confirmed by instrumentation: the handler's own `.focus()`
    // call lands correctly (document.activeElement matches immediately inside the handler), but
    // a synchronous assertion straight after `user.keyboard()` intermittently still sees the
    // pre-move element. ZimmProductGallery's own identical dot-bar test needs no such wait
    // because that component isn't rendered inside a focus trap.
    // 1000ms default timeout confirmed flaky under full-suite load (reliable in isolation) —
    // FocusLock's rAF reconciliation can take longer under worker contention. 3000ms gives it
    // real headroom without masking a genuine regression (a true failure still fails, just later).
    const options = { timeout: 8000 };
    thumb1.focus();
    await user.keyboard('{ArrowRight}');
    await waitFor(() => expect(thumb2).toHaveFocus(), options);
    await user.keyboard('{ArrowLeft}');
    await waitFor(() => expect(thumb1).toHaveFocus(), options);
    await user.keyboard('{ArrowLeft}');
    await waitFor(() => expect(thumb7).toHaveFocus(), options);
  });
});

describe('ZimmGalleryOverlay — image content (AC 18)', () => {
  test('renders the full media array as tiles, first one eager (LCP priority)', async () => {
    wrap(<ZimmGalleryOverlay isOpen productName="Denim Dress" onClose={vi.fn()} media={SEVEN} />);
    const firstImg = await screen.findByAltText('Photo 1');
    expect(firstImg).toHaveAttribute('loading', 'eager');
    expect(screen.getByAltText('Photo 7')).toHaveAttribute('loading', 'lazy');
  });
});

describe('ZimmGalleryOverlay — live region', () => {
  test("announces the current image's alt text and position", async () => {
    wrap(<ZimmGalleryOverlay isOpen productName="Denim Dress" onClose={vi.fn()} media={SEVEN} />);
    expect(await screen.findByText('Photo 1. Image 1 of 7.')).toBeInTheDocument();
  });

  test('scrolling to a new item (IntersectionObserver) updates the announced position', async () => {
    wrap(<ZimmGalleryOverlay isOpen productName="Denim Dress" onClose={vi.fn()} media={SEVEN} />);
    await screen.findByText('Photo 1. Image 1 of 7.');
    const thirdItem = screen.getByTestId('zimm-gallery-overlay-item-2');

    act(() => {
      latestObserverCallback?.(
        [
          {
            isIntersecting: true,
            intersectionRatio: 1,
            target: thirdItem,
          } as unknown as IntersectionObserverEntry,
        ],
        {} as IntersectionObserver,
      );
    });

    expect(screen.getByText('Photo 3. Image 3 of 7.')).toBeInTheDocument();
  });
});

describe('ZimmGalleryOverlay — colour selector (AC 15)', () => {
  const TWO_COLOURS = [
    { value: 'a', name: 'Pink', imageUrl: 'https://example.test/a.jpg' },
    { value: 'b', name: 'Navy', imageUrl: 'https://example.test/b.jpg' },
  ];

  test('renders "Also available in" + a swatch per colour when there are multiple', async () => {
    wrap(
      <ZimmGalleryOverlay
        isOpen
        productName="Denim Dress"
        onClose={vi.fn()}
        media={SEVEN}
        colourValues={TWO_COLOURS}
        selectedColourValue="a"
      />,
    );
    await screen.findByRole('dialog');
    expect(screen.getAllByText('Also available in').length).toBeGreaterThan(0);
    expect(screen.getAllByRole('radio', { name: 'Pink' }).length).toBeGreaterThan(0);
    expect(screen.getAllByRole('radio', { name: 'Navy' }).length).toBeGreaterThan(0);
  });

  test('SFCC-731 fix — renders "Colour: <name>" (no swatch row, no "Also available in") when there is only one colour, matching the PDP', async () => {
    wrap(
      <ZimmGalleryOverlay
        isOpen
        productName="Denim Dress"
        onClose={vi.fn()}
        media={SEVEN}
        colourValues={[TWO_COLOURS[0]]}
      />,
    );
    await screen.findByRole('dialog');
    expect(screen.queryByText('Also available in')).not.toBeInTheDocument();
    expect(screen.getAllByText('Colour:').length).toBeGreaterThan(0);
    expect(screen.getAllByTestId('pdp-colour-selected-name')[0]).toHaveTextContent('Pink');
    expect(screen.queryByRole('radio', { name: 'Pink' })).not.toBeInTheDocument();
  });

  test('renders nothing when no colour values are supplied', async () => {
    wrap(<ZimmGalleryOverlay isOpen productName="Denim Dress" onClose={vi.fn()} media={SEVEN} />);
    await screen.findByRole('dialog');
    expect(screen.queryByText('Also available in')).not.toBeInTheDocument();
    expect(screen.queryByText('Colour:')).not.toBeInTheDocument();
  });
});

